CREATE OR REPLACE FUNCTION public.app_admin_list_challenge_participation_videos(p_challenge_id uuid DEFAULT NULL::uuid, p_participation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_result JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'id', v.id,
                'participation_id', v.participation_id,
                'video_url', v.video_url,
                'thumbnail_url', v.thumbnail_url,
                'created_at', v.created_at,
                'challenge_id', cp.challenge_id,
                'user_id', cp.user_id,
                'challenge_title', c.title
            )
            ORDER BY v.created_at DESC
        ),
        '[]'::JSONB
    ) INTO v_result
    FROM app.challenge_participation_videos v
    JOIN app.challenge_participations cp ON cp.id = v.participation_id
    JOIN app.challenges c ON c.id = cp.challenge_id
    WHERE (p_challenge_id IS NULL OR cp.challenge_id = p_challenge_id)
      AND (p_participation_id IS NULL OR v.participation_id = p_participation_id);

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'videos', v_result);
END;
$function$

